package ru.faktish;
import com.google.gson.*;import ru.faktish.config.*;import ru.faktish.db.*;import ru.faktish.vk.*;import ru.faktish.core.*;import ru.faktish.commands.*;import java.nio.file.*;import java.util.*;
public class Main{
 public static void main(String[] args)throws Exception{System.out.println("=== Faktish VK Bot Java 2.0 ===");Config cfg=new Config();if(cfg.token().isBlank()){System.err.println("VK токен не указан в config.properties");return;}long gid=cfg.group();if(gid==0){System.err.println("Укажите group_id. Для текущего бота: 240750314");return;}Database db=new Database(cfg.db());VkClient vk=new VkClient(cfg.token(),cfg.api(),gid);vk.init();System.out.println("Long Poll запущен для группы "+gid);
  while(true){try{JsonObject p=vk.poll();if(p==null||!p.has("failed"))handle(p,vk,db); }catch(Exception e){e.printStackTrace();Thread.sleep(2000);try{vk.init();}catch(Exception ignored){}}}
 }
 static void handle(JsonObject p,VkClient vk,Database db)throws Exception{if(p==null||!p.has("updates"))return;for(JsonElement e:p.getAsJsonArray("updates")){JsonObject u=e.getAsJsonObject();String type=u.get("type").getAsString();JsonObject o=u.getAsJsonObject("object");if(type.equals("message_new")){long peer=o.get("peer_id").getAsLong(),from=o.get("from_id").getAsLong();String text=o.has("text")?o.get("text").getAsString().trim():"";if(from<=0||text.isBlank())continue;db.registerChat(peer);String[] a=text.split("\\s+");String cmd=a[0].replaceFirst("^[/!]+","").toLowerCase(Locale.ROOT);new Router(new Context(vk,db,peer,from,a,cmd)).run();}else if(type.equals("message_event")){JsonObject pld=new JsonObject();if(o.has("payload")){try{JsonElement pe=o.get("payload");pld=pe.isJsonObject()?pe.getAsJsonObject():JsonParser.parseString(pe.getAsString()).getAsJsonObject();}catch(Exception ignored){}}String action=pld.has("action")?pld.get("action").getAsString():"";long user=o.get("user_id").getAsLong();long peer=o.get("peer_id").getAsLong();if(action.equals("case_buy")){new Router(new Context(vk,db,peer,user,new String[]{"/кейс","buy"},"кейс")).callback("case_buy",pld);}else if(action.equals("case_open")){new Router(new Context(vk,db,peer,user,new String[]{"/кейс","open"},"кейс")).callback("case_open",pld);}else if(action.equals("case_info")){new Router(new Context(vk,db,peer,user,new String[]{"/кейс","info"},"кейс")).callback("case_info",pld);}else if(action.equals("case_mine")){new Router(new Context(vk,db,peer,user,new String[]{"/кейс","mine"},"кейс")).callback("case_mine",pld);}else if(action.equals("duel_accept")){new Router(new Context(vk,db,peer,user,new String[]{"/duel","accept"},"duel")).callback("duel_accept",pld);}else if(action.equals("duel_delete")){new Router(new Context(vk,db,peer,user,new String[]{"/duel","delete"},"duel")).callback("duel_delete",pld);}}} }
}
